codeSnippet.JAVA:
import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        String reversed = new StringBuilder(s).reverse().toString();
        System.out.println(String.valueOf(s.equals(reversed)));
    }
}

